import {guidance} from './guidance.js';
import {USERS,dashboard,detail,act,advance,load} from './domain.js';
import {iso,timestamp,nextSession} from './sla.js';
import {seed,SCENARIOS,VARIANTS} from './seeds.js';
import {reports} from './reports.js';
import {readStorage,saveStorage} from './storage.js';
const $=s=>document.querySelector(s), esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const boot=(()=>{try{return readStorage(localStorage);}catch{return {data:seed(),notice:'Storage không khả dụng; demo tiếp tục trong memory.'};}})();
let data=boot.data, filter={from:'2026-10-01',to:'2026-10-31',priority:'',agent:''};
$('#storage-notice').textContent=boot.notice;
const time=v=>v?iso(v).slice(0,19).replace('T',' '):'—';
const minute=n=>n<60?'Dưới 1 phút':n<3600?`${Math.floor(n/60)} phút`:`${Math.floor(n/3600)} giờ ${Math.floor(n%3600/60)} phút`;
const capacity=n=>n<3?'Dưới giới hạn':n===3?'Đạt giới hạn':'Quá tải';
const status=s=>`<span class="badge">${esc(s)}</span>`;
const priority=p=>`<span class="badge ${p==='HIGH'?'status-high':''}">${p==='HIGH'?'High':'Normal'}</span>`;
const link=t=>`<a href="#ticket/${t.id}">#${t.id} · ${esc(t.title)}</a>`;
const field=(name,label,type='textarea')=>`<label>${label}${type==='textarea'?`<textarea name="${name}" required></textarea>`:`<input name="${name}" required>`}</label>`;
const table=(headers,rows,label)=>`<div class="table-wrap" role="region" aria-label="${esc(label)}" tabindex="0"><table><thead><tr>${headers.map(h=>`<th scope="col">${h}</th>`).join('')}</tr></thead><tbody>${rows.length?rows.map(r=>`<tr>${r.map(v=>`<td>${v}</td>`).join('')}</tr>`).join(''):`<tr><td colspan="${headers.length}" class="empty">Chưa có dữ liệu trong bộ mẫu / bộ lọc hiện tại.</td></tr>`}</tbody></table></div>`;
const slaLabel=s=>({breached:'Vi phạm SLA',met:'Đạt SLA',pending:'Chưa có kết quả'}[s]??s);
const warningLabel=s=>({breached:'Vi phạm SLA',due:'Đến hạn',emphasized:'Gần đến hạn',soft:'Sắp đến hạn',none:'Không cảnh báo'}[s]??s);
const runLabel=(t,k)=>t.sla[k].running?'Đang chạy':k==='resolution' && t.state==='Waiting for Customer'?'Tạm dừng':'Đã hoàn tất';
const contextLabel=s=>({before_request:'Trước yêu cầu review',during_wait:'Trong thời gian chờ',none:'Chưa ghi nhận vi phạm trong bối cảnh này'}[s]??s);
const ticketTable=(rows,internal=false)=>table(['Ticket','Ưu tiên','Trạng thái','Tạo lúc',...(internal?['Phản hồi đầu','Giải quyết']:[])],rows.map(t=>[link(t),priority(t.priority),status(t.state),time(t.created_at),...(internal?['first_response','resolution'].map(k=>`${slaLabel(t.sla[k].status)} · ${runLabel(t,k)} · ${warningLabel(t.sla[k].warning_level)}<br>${minute(t.sla[k].remaining_seconds)}`):[])]),'Danh sách ticket, cuộn ngang khi cần');
function feedback(message,error=false){$('#feedback').textContent=message;$('#feedback').className=error?'error':'success';}
function persist(){try{$('#storage-notice').textContent=saveStorage(localStorage,data);}catch{$('#storage-notice').textContent='Không lưu được; demo tiếp tục trong memory.';}}
function home(){return USERS[data?.identity]==='Agent'?'agent':USERS[data?.identity]==='Manager'?'manager':'customer';}
function navigateHome(){location.hash=home();render();}
function customer(){
  const rows=dashboard(data);
  return `<p class="section-lead">Gửi yêu cầu và theo dõi phản hồi của đội hỗ trợ.</p><div class="columns"><section class="card"><h2>Tạo ticket</h2><form data-action="create" class="stack">${field('title','Tiêu đề','input')}${field('description','Mô tả')}<label>Ưu tiên<select name="priority"><option value="HIGH">High</option><option value="NORMAL">Normal</option></select></label><button>Tạo ticket</button></form></section><section class="card"><h2>Ticket của bạn <span class="badge">${rows.length}</span></h2>${rows.length?ticketTable(rows):'<p class="empty">Bạn chưa có ticket. Điền biểu mẫu bên cạnh để gửi yêu cầu đầu tiên.</p>'}</section></div>`;
}
function agent(){
  const vm=dashboard(data);
  return `<div class="load-pill">Agent ${data.identity} · ${vm.load} In Progress · ${capacity(vm.load)}</div><section class="card"><h2>Hàng đợi New</h2><p class="muted">Gợi ý: High → hạn phản hồi sớm → tạo sớm. Bạn tự chọn ticket để nhận.</p>${table(['Mã','Tiêu đề','Ưu tiên','Hạn phản hồi','Thời điểm tạo','Thao tác'],vm.queue.map(t=>[`#${t.id}`,esc(t.title),priority(t.priority),time(t.first_response_due_at),time(t.created_at),`<button data-claim="${t.id}" ${vm.load>=3?'disabled title="Agent đã đạt giới hạn nhận"':''}>Nhận</button>${vm.load>=3?'<p class="muted">Đạt giới hạn nhận</p>':''}`]),'Hàng đợi New, cuộn ngang khi cần')}</section><section class="card"><h2>Ticket phụ trách</h2>${ticketTable(vm.mine,true)}</section>`;
}
function reportUI(){
  const r=reports(data,filter), names={'M-01':'Phản hồi đầu đạt SLA','M-02':'Ticket đã đóng đạt SLA giải quyết','M-03':'Ticket đã đóng từng bị khách từ chối'};
  return `<section class="card"><h2 id="manager-reports" tabindex="-1">Báo cáo vận hành</h2><form id="report-filter" class="report-filter"><label>Từ ngày<input type="date" name="from" value="${filter.from}" required></label><label>Đến hết ngày<input type="date" name="to" value="${filter.to}" required></label><label>Ưu tiên<select name="priority"><option value="">Tất cả</option>${['HIGH','NORMAL'].map(p=>`<option ${filter.priority===p?'selected':''}>${p}</option>`).join('')}</select></label><label>Agent<select name="agent"><option value="">Tất cả</option>${[3,4,5].map(a=>`<option value="${a}" ${filter.agent==a?'selected':''}>Agent ${a}</option>`).join('')}</select></label><button>Áp dụng</button></form><p class="muted">Tại ${time(data.clock)} UTC+7. Kỳ ${filter.from} → hết ${filter.to}, tương đương [from, ngày kế tiếp 00:00). M-01 theo ngày tạo; M-02/03 theo ngày Closed. M-04…07 là snapshot, không lọc kỳ. M-06 luôn tất cả ưu tiên.</p></section><div class="metric-grid">${Object.entries(names).map(([m,name])=>`<section class="card metric"><span class="eyebrow">${m}</span><h3>${name}</h3><p class="value">${r[m].display}</p><p class="muted">Tử số ${r[m].numerator} / mẫu số ${r[m].denominator}</p>${m==='M-01'?`<p>N · Chưa có kết quả phản hồi đầu: ${r[m].pending_count}</p>`:`<p>N · Còn ${r[m].unclosed_count} ticket chưa Closed, chưa tính vào các tỷ lệ này.</p><p class="muted">Ticket chưa đóng tại thời điểm xem, cùng bộ lọc, không giới hạn ngày tạo.</p><details class="explanation"><summary>Giải thích thêm về N</summary><p>N không là phần bù mẫu số: mẫu số chọn ticket Closed trong kỳ, N là snapshot ticket chưa đóng tại thời điểm xem.</p></details>`}</section>`).join('')}</div><section class="card"><h2>M-04 · Chưa Closed vi phạm SLA</h2>${table(['Ticket','Phản hồi đầu vi phạm SLA','Giải quyết vi phạm SLA'],r['M-04'].map(t=>[`<a href="#ticket/${t.id}">#${t.id}</a>`,t.first_response_breached?'Có':'Không',t.resolution_breached?'Có':'Không']),'M-04')}</section><section class="card"><h2>M-05 · Resolved chờ xác nhận</h2>${table(['Ticket','Resolved gần nhất','Chờ theo giờ lịch'],r['M-05'].map(t=>[`<a href="#ticket/${t.id}">#${t.id}</a>`,time(t.resolved_at),minute(t.wait_calendar_seconds)]),'M-05')}</section><section class="card"><h2 id="manager-load" tabindex="-1">M-06 · Tải thực — tính tất cả mức ưu tiên</h2>${table(['Agent','In Progress','Mức tải','Waiting','Resolved','Closed'],r['M-06'].map(t=>[`Agent ${t.agent_id}`,t.in_progress_count,capacity(t.in_progress_count),t.counts_by_status['Waiting for Customer'],t.counts_by_status.Resolved,t.counts_by_status.Closed]),'M-06')}</section><section class="card"><h2>M-07 · Bối cảnh chờ Manager review</h2><p class="muted">Giờ lịch chờ và giây làm việc chồng SLA giải quyết; không tự quy lỗi hoặc xếp hạng.</p>${table(['Ticket / review','Yêu cầu','Hoàn tất','Chờ giờ lịch','Chồng SLA (giây làm việc)','Bối cảnh vi phạm SLA'],r['M-07'].map(t=>[`<a href="#ticket/${t.ticket_id}">#${t.ticket_id} / ${t.review_key}</a>`,time(t.requested_at),time(t.completed_at),minute(t.wait_calendar_seconds),t.wait_overlap_seconds,contextLabel(t.breach_context)]),'M-07')}</section>`;
}
function manager(){
  const rows=dashboard(data), open=rows.filter(t=>t.open_review);
  return `<nav class="manager-jumps" aria-label="Đi tới nội dung Manager">${[['manager-reviews','Review mở'],['manager-reports','Báo cáo'],['manager-load','Tải Agent'],['manager-tickets','Tất cả ticket']].map(([id,label])=>`<a href="#${id}" data-jump="${id}">${label}</a>`).join('')}</nav><section class="card"><h2 id="manager-reviews" tabindex="-1">Review đang mở <span class="badge">${open.length}</span></h2>${table(['Ticket','Review','Yêu cầu lúc','Trạng thái'],open.map(t=>[link(t),t.open_review,time(t.reviews.at(-1).requested_at),status(t.state)]),'Review đang mở')}</section>${reportUI()}<section class="card"><h2 id="manager-tickets" tabindex="-1">Tất cả ticket</h2>${ticketTable(rows,true)}</section>`;
}
function actionForm(action,label,key,keyLabel,id){return `<form data-action="${action}" data-id="${id}" class="stack form-action"><h3>${label}</h3>${field(key,keyLabel)}<button>${label}</button></form>`;}
function ticket(id){
  const t=detail(data,id),role=USERS[data.identity],customer=role==='Customer';
  let out=`<a href="#${home()}">← Về danh sách</a><section class="card" style="margin-top:16px"><div class="actions">${priority(t.priority)}${status(t.state)}</div><h2 style="margin-top:18px">#${t.id} · ${esc(t.title)}</h2><p class="preserve">${esc(t.description)}</p><p class="muted">Tạo ${time(t.created_at)} UTC+7</p></section>`;
  if(!customer){
    out+=`<section class="card" data-internal="sla"><h2>SLA nội bộ</h2><p class="muted">${t.resolution_result_final?'Kết quả cuối · Closed':t.state==='Resolved'?'Kết quả tạm thời · chờ Customer xác nhận':'Theo clock mô phỏng hiện hành'}</p><div class="sla-grid">${['first_response','resolution'].map(k=>{const s=t.sla[k];return `<div class="sla ${s.warning_level}"><h3>${k==='first_response'?'Phản hồi đầu':'Giải quyết'}</h3><div class="big-clock">${s.remaining_seconds} giây còn lại</div><p>Đã tiêu: ${s.consumed_seconds} giây</p><p>${runLabel(t,k)} · ${slaLabel(s.status)} · ${warningLabel(s.warning_level)}</p><p>Hạn ${s.running?'đang áp dụng':'đánh giá'}: ${time(s.due_at)}</p></div>`;}).join('')}</div>${t.snapshot?`<p class="muted">Snapshot lúc nhận ${time(t.snapshot.assigned_at)} · P ${slaLabel(t.snapshot.first_response_sla_status_at_assignment)} · G ${slaLabel(t.snapshot.resolution_sla_status_at_assignment)}</p>`:''}</section>`;
  }
  out+=`<section class="card"><h2>Hội thoại công khai</h2>${t.messages.filter(m=>m.visibility==='PUBLIC').map(m=>`<article class="message"><span class="muted">${USERS[m.actor_id]} ${m.actor_id} · ${time(m.created_at)}</span><p>${esc(m.content)}</p></article>`).join('')||'<p class="empty">Chưa có phản hồi công khai.</p>'}`;
  if(['New','In Progress','Waiting for Customer'].includes(t.state) && role!=='Manager') out+=actionForm('message','Gửi tin nhắn','content','Nội dung công khai',t.id);
  if(customer && t.state==='Resolved') out+=`<div class="form-action"><button data-confirm="${t.id}">Xác nhận đã giải quyết</button></div>`+actionForm('reject','Từ chối kết quả','reason','Lý do từ chối',t.id);
  out+='</section>';
  if(!customer){
    out+=`<section class="card" data-internal="notes"><h2>Ghi chú nội bộ</h2>${t.messages.filter(m=>m.visibility==='INTERNAL').map(m=>`<article class="message"><span class="muted">Agent ${m.actor_id} · ${time(m.created_at)}</span><p>${esc(m.content)}</p></article>`).join('')||'<p class="muted">Chưa có ghi chú.</p>'}`;
    if(role==='Agent' && ['In Progress','Waiting for Customer'].includes(t.state))out+=actionForm('note','Thêm ghi chú','content','Nội dung nội bộ',t.id);
    out+='</section>';
    out+=`<section class="card" data-internal="reviews"><h2>Review & phương án</h2><p>Từ chối: ${t.rejection_count} · ${t.open_review?'Cần Manager can thiệp':'Không có review mở'}</p>${t.reviews.map(r=>`<article class="message"><h3>${r.review_key} · ${r.completed_at?'Hoàn tất':'Đang mở'}</h3><p class="muted">Yêu cầu ${time(r.requested_at)} · hoàn tất ${time(r.completed_at)}</p>${r.handling_plan?`<p class="preserve">Nguyên nhân: ${esc(r.handling_plan.unresolved_reason)}</p><p class="preserve">Tiếp theo: ${esc(r.handling_plan.next_action)}</p><p>N · Cần ý kiến chuyên môn: ${r.handling_plan.needs_expert_input?'Có':'Không'} (chỉ cờ ghi nhận)</p><p class="preserve">${esc(r.handling_plan.expert_note)}</p>`:''}</article>`).join('')}`;
    if(role==='Manager' && t.open_review)out+=`<form data-action="review" data-id="${t.id}" class="stack form-action">${field('unresolved_reason','Nguyên nhân chưa giải quyết được')}${field('next_action','Hướng xử lý tiếp theo')}<label class="checkbox"><input name="needs_expert_input" type="checkbox">Cần ý kiến chuyên môn (chỉ ghi nhận)</label><label>Ghi chú chuyên môn (tùy chọn)<textarea name="expert_note"></textarea></label><button>Ghi phương án & hoàn tất review</button></form>`;
    out+='</section>';
    if(role==='Agent' && t.state==='In Progress') out+=`<section class="card"><h2>Thao tác xử lý</h2><button data-waiting="${t.id}" ${t.sla.first_response.running?'disabled':''}>Waiting for Customer</button>${t.sla.first_response.running?'<p class="muted">Cần phản hồi công khai đầu tiên trước khi Waiting.</p>':''}<form data-action="resolve" data-id="${t.id}" class="stack form-action">${field('resolution_summary','Kết quả giải quyết công khai')}<button ${t.open_review?'disabled':''}>Resolved</button>${t.open_review?'<p>N · Cần Manager hoàn tất review.</p>':''}</form></section>`;
  }
  return out;
}
export function render(){
  if(!data){$('#main').innerHTML='<section class="card"><h2>Cần khôi phục bộ mẫu</h2><p>Dữ liệu lưu chưa được diễn giải. Bấm Khôi phục bộ mẫu để tiếp tục.</p></section>';return;}
  const role=USERS[data.identity];$('#identity').value=data.identity;$('#scenario').value=data.scenario;$('#variant').value=data.variant;$('#variant-label').hidden=data.scenario!=='DEMO-06';$('#clock').textContent=time(data.clock)+' UTC+7';$('#clock-target').value=iso(data.clock).slice(0,19);$('#guide').textContent=guidance(data.scenario,data.variant,role,data.identity);$('#guide-title').textContent=data.scenario+' · Hướng dẫn '+role;$('#control-summary').textContent=`${role} ${data.identity} · ${data.scenario}${data.scenario==='DEMO-06'?' · '+VARIANTS.find(v=>v.id===data.variant).name:''} · ${time(data.clock)} UTC+7 · Clock đứng yên`;$('#identity-badge').textContent=`${role} ${data.identity} · mô phỏng`;
  let route=location.hash.slice(1)||home();
  if(!route.startsWith('ticket/') && route!==home()){route=home();history.replaceState(null,'','#'+route);feedback('Màn hình được giới hạn theo danh tính demo.',true);}
  try {
    $('#main').innerHTML=route.startsWith('ticket/')?ticket(Number(route.slice(7))):route==='customer'?customer():route==='agent'?agent():manager();
    $('#page-title').textContent=route.startsWith('ticket/')?'Chi tiết ticket':route==='customer'?'Ticket của bạn':route==='agent'?'Không gian Agent':'Tổng quan Manager';
  } catch(e){$('#main').innerHTML=`<section class="card"><h2>${e.status||'Lỗi'} · ${esc(e.message)}</h2><a href="#${home()}">Về màn hình của bạn</a></section>`;}
  document.querySelectorAll('nav a').forEach(a=>{a.classList.toggle('active',a.dataset.view===route);if(a.dataset.view===route)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});
}
$('#scenario').innerHTML=SCENARIOS.map(s=>`<option value="${s.id}">${s.name}</option>`).join('');$('#variant').innerHTML=VARIANTS.map(v=>`<option value="${v.id}">${v.name}</option>`).join('');
function replace(){data=seed($('#scenario').value,$('#variant').value);feedback('Đã thay thế dữ liệu demo bằng bộ mẫu dựng sẵn.');persist();navigateHome();}
$('#scenario').addEventListener('change',replace);$('#variant').addEventListener('change',replace);$('#reset').addEventListener('click',replace);
$('#identity').addEventListener('change',()=>{if(!data)return;data.identity=Number($('#identity').value);feedback('Đã đổi danh tính mô phỏng; clock và dữ liệu giữ nguyên.');persist();navigateHome();});
function changeClock(value){try{if(!data)throw Error('Cần khôi phục bộ mẫu');advance(data,value);feedback('Đã tiến clock mô phỏng.');persist();render();}catch(e){feedback(e.message,true);}}
document.querySelectorAll('[data-advance]').forEach(b=>b.addEventListener('click',()=>data&&changeClock(timestamp(data.clock)+Number(b.dataset.advance))));
$('#next-session').addEventListener('click',()=>data&&changeClock(nextSession(data.clock)));
$('#clock-form').addEventListener('submit',e=>{e.preventDefault();let value=$('#clock-target').value;if(value.length===16)value+=':00';changeClock(value+'+07:00');});
function execute(action,id,payload={}){try{const result=act(data,action,id,payload);feedback('Thao tác đã được ghi nhận.');persist();if(action==='create'||action==='claim')location.hash=`ticket/${result}`;render();}catch(e){feedback(`${e.message}${e.code?' · '+e.code:''}`,true);}}
$('#main').addEventListener('click',e=>{const jump=e.target.closest('[data-jump]');if(jump){e.preventDefault();const target=document.getElementById(jump.dataset.jump);target?.focus({preventScroll:true});target?.scrollIntoView();return;}const b=e.target.closest('button');if(!b)return;for(const a of ['claim','confirm','waiting'])if(b.dataset[a])execute(a,Number(b.dataset[a]));});
$('#main').addEventListener('submit',e=>{e.preventDefault();const f=e.target,p=Object.fromEntries(new FormData(f));if(f.id==='report-filter'){try{reports(data,p);filter=p;render();feedback('Đã áp dụng kỳ và bộ lọc.');}catch(err){feedback(err.message,true);}return;}if(!f.dataset.action)return;if(f.dataset.action==='review')execute('review',Number(f.dataset.id),{handling_plan:{...p,needs_expert_input:f.elements.needs_expert_input.checked}});else execute(f.dataset.action,Number(f.dataset.id),p);});
window.addEventListener('hashchange',render);render();
